{"task": {"current_case": {"facts": "Alice and Bob got married on April 5th, 2012. Alice and Bob were legally separated under a decree of divorce on September 16th, 2017.", "question": "Section 7703(a)(2) applies to Alice for the year 2018."}, "unchanged_legal_program": {"input_fields_json": "{"query_person":{"type":"string","description":"被查询个人。"},"query_year":{"type":"integer","description":"进行婚姻状态判断的公历纳税年度；判断时点为该年 12 月 31 日。"},"legal_separation_decrees":{"type":"array|null","description":"已解析的有向法令事实；每个对象严格为 {individual:string,spouse:string,decree_type:string,effective_date:string,end_date:string|null,open_ended:boolean}。decree_type 只能是 divorce 或 separate_maintenance；日期为 YYYY-MM-DD，区间包含端点。end_date 为 null 只有在 open_ended 为 true 时才明确持续；否则结束状态未知。null 数组表示未读取或未解析，[] 表示已解析且无记录。"}}", "name": "legal_separation_status", "program": "def apply(inputs,premises):
    person=inputs.get('query_person')
    year=inputs.get('query_year')
    if not isinstance(person,str) or type(year) is not int:
        return {'handled':False,'answer':None}
    close=str(year)+'-12-31'
    calendar_year(close)
    decrees=inputs.get('legal_separation_decrees')
    if decrees is None:
        return {'handled':False,'answer':None}
    if not isinstance(decrees,list):
        raise TypeError('legal_separation_decrees must be an array or null')
    uncertain=False
    for record in decrees:
        if not isinstance(record,dict):
            raise TypeError('Each decree must be an object')
        individual=record.get('individual'); spouse=record.get('spouse'); kind=record.get('decree_type')
        start=record.get('effective_date'); end=record.get('end_date'); opened=record.get('open_ended')
        if not isinstance(individual,str) or not isinstance(spouse,str) or kind not in ('divorce','separate_maintenance') or not isinstance(start,str) or type(opened) is not bool:
            raise ValueError('Malformed legal-separation decree')
        calendar_year(start)
        if end is not None:
            if not isinstance(end,str) or opened:
                raise ValueError('A closed decree interval requires open_ended false')
            calendar_year(end)
            if end<start:
                raise ValueError('Decree interval ends before it begins')
        if individual!=person or start>close:
            continue
        if end is not None and end>=close:
            return {'handled':True,'answer':'Entailment'}
        if end is None and opened:
            return {'handled':True,'answer':'Entailment'}
        if end is None:
            uncertain=True
    if uncertain:
        return {'handled':False,'answer':None}
    return {'handled':True,'answer':'Contradiction'}", "query_clause": "7703(a)(2)", "scope": "exact_clause", "source_quote": "(2) an individual legally separated from his spouse under a decree of divorce or of separate maintenance shall not be considered as married."}}, "output_schema": {"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["query_person", "query_year", "decree_resolution", "decree_evidence", "witnesses", "unresolved"], "properties": {"query_person": {"type": "string", "minLength": 1}, "query_year": {"type": "integer"}, "decree_resolution": {"enum": ["resolved", "unknown"]}, "decree_evidence": {"type": "array", "items": {"oneOf": [{"type": "object", "additionalProperties": false, "required": ["evidence_type", "individual", "spouse", "decree_type", "effective_date"], "properties": {"evidence_type": {"const": "onset_only"}, "individual": {"type": "string", "minLength": 1}, "spouse": {"type": "string", "minLength": 1}, "decree_type": {"enum": ["divorce", "separate_maintenance"]}, "effective_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}, {"type": "object", "additionalProperties": false, "required": ["evidence_type", "individual", "spouse", "decree_type", "effective_date"], "properties": {"evidence_type": {"const": "effective_through_close"}, "individual": {"type": "string", "minLength": 1}, "spouse": {"type": "string", "minLength": 1}, "decree_type": {"enum": ["divorce", "separate_maintenance"]}, "effective_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}, {"type": "object", "additionalProperties": false, "required": ["evidence_type", "individual", "spouse", "decree_type", "effective_date", "end_date"], "properties": {"evidence_type": {"const": "closed_interval"}, "individual": {"type": "string", "minLength": 1}, "spouse": {"type": "string", "minLength": 1}, "decree_type": {"enum": ["divorce", "separate_maintenance"]}, "effective_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}, "end_date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}}}]}}, "witnesses": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["field", "quote"], "properties": {"field": {"enum": ["facts", "question"]}, "quote": {"type": "string", "minLength": 1}}}}, "unresolved": {"type": "array", "items": {"type": "string", "minLength": 1}}}}}
